import Item from './item';
import { t } from '../../locale/locale';

export default class Indent extends Item {
  element() {
    const { tag } = this;
    return super.element()
      .child(t(`toolbar.${tag}`))
      .on('click', () => this.change(tag));
  }

  setState(disabled) {
    this.el.disabled(disabled);
  }
}
